12	/**
13	 * Rejects a create-owner request whose derived {@link OwnerIdentity identity key} exactly
14	 * matches an existing owner's, responding 409. This is the single duplicate check: the
15	 * former separate telephone, email and household checks are all expressed through the one
16	 * key (see {@link OwnerIdentity}), so two owners collide only when their <em>whole</em> key
17	 * matches. Because the telephone is part of the key, members of the same household with
18	 * different telephones have different keys and are both allowed.
19	 *
20	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the
21	 * request's telephone and email are in stored form; the household id is the one the request
22	 * would be assigned (see {@link OwnerHouseholds#assignedId}), matching what
23	 * {@link AssignOwnerHousehold} later stores.
24	 */
25	public class RejectDuplicateOwnerIdentity {
26	
27	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws DuplicateOwnerException {
29	        Collection<Owner> existing = ownerRepository.findAll();
30	        String householdId = OwnerHouseholds.assignedId(Boolean.TRUE.equals(request.getSharesHousehold()),
31	                request.getLastName(), request.getAddress(), existing);
32	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
33	        for (Owner owner : existing) {
34	            if (identityKey.equals(OwnerIdentity.of(owner))) {
35	                throw new DuplicateOwnerException(identityKey);
36	            }
37	        }
38	    }
