1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Locale;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.model.Sha256;
9	
10	/**
11	 * The single definition of what a "household" is: owners sharing the same last name and
12	 * address, compared case-insensitively with runs of whitespace collapsed to a single
13	 * space. Shared by {@link RejectDuplicateOwnerHousehold} (which forbids an unopted
14	 * duplicate) and {@link AssignOwnerHousehold} (which links opted-in members), so both
15	 * decide membership identically.
16	 */
17	final class OwnerHouseholds {
18	
19	    private static final int ID_HEX_LENGTH = 12;
20	
21	    private OwnerHouseholds() {
22	    }
23	
24	    /** The existing owners that share the household identified by {@code lastName} and {@code address}. */
25	    static List<Owner> members(Iterable<Owner> owners, String lastName, String address) {
26	        String canonicalLastName = canonical(lastName);
27	        String canonicalAddress = canonical(address);
28	        List<Owner> members = new ArrayList<>();
29	        for (Owner existing : owners) {
30	            if (canonicalLastName.equals(canonical(existing.getLastName()))
31	                    && canonicalAddress.equals(canonical(existing.getAddress()))) {
32	                members.add(existing);
33	            }
34	        }
35	        return members;
36	    }
37	
38	    /**
39	     * The household id an owner with this {@code lastName} and {@code address} would be
40	     * assigned: the shared id when it opts in ({@code sharesHousehold}) and existing owners
41	     * already form that household, otherwise {@code null} (it stands alone). Shared by
42	     * {@link RejectDuplicateOwnerIdentity} (to derive the would-be identity key) and
43	     * {@link AssignOwnerHousehold} (which then links the members), so both agree.
44	     */
45	    static String assignedId(boolean sharesHousehold, String lastName, String address, Iterable<Owner> owners) {
46	        if (!sharesHousehold || members(owners, lastName, address).isEmpty()) {
47	            return null;
48	        }
49	        return householdId(lastName, address);
50	    }
51	
52	    /**
53	     * A stable identifier for the household: derived from the canonical last name and
54	     * address, so every member computes the same value regardless of creation order.
55	     */
56	    static String householdId(String lastName, String address) {
57	        String key = canonical(lastName) + "�" + canonical(address);
58	        return Sha256.upperHex(key, ID_HEX_LENGTH);
59	    }
60	
61	    /** Trim, collapse internal whitespace to a single space, and lower-case for comparison. */
62	    private static String canonical(String value) {
63	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
64	    }
65	}
