15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
26	    @Mapping(target = "initials", expression = "java(initials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    Owner toOwner(OwnerDto ownerDto);
37	
38	    /** Format an owner's name as 'LastName, FirstName' for display. */
39	    default String displayName(Owner owner) {
40	        return owner.getLastName() + ", " + owner.getFirstName();
41	    }
42	
43	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
44	    default String initials(Owner owner) {
45	        return initial(owner.getFirstName()) + initial(owner.getLastName());
46	    }
47	
48	    private static String initial(String name) {
49	        return Character.toUpperCase(name.charAt(0)) + ".";
50	    }
51	
52	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
53	     * last two digits of the registrationDate year. */
54	    default String membershipNumber(Owner owner) {
55	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
56	            return null;
57	        }
58	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
59	    }
60	
61	    /** The owner's membership level from 1 to 3: starts at 1, plus 1 when an email is present,
62	     * plus 1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure). */
63	    default int membershipLevel(Owner owner) {
64	        int level = 1;
65	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
66	        if (hasEmail) {
67	            level++;
68	        }
69	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
70	            level++;
71	        }
72	        return Math.min(level, 3);
73	    }
74	
75	    /** The owner's canonical region: the REGION segment of the customer code (see
76	     * {@link CustomerCode}), or null when the customer code is unset. */
77	    default String locality(Owner owner) {
78	        return CustomerCode.region(owner.getCustomerCode());
79	    }
80	
81	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
82	    default String contactPreference(Owner owner) {
83	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
84	        return hasEmail ? "EMAIL" : "PHONE";
